41	const systemPrompt = (set: QuestionSet) =>
42	  `You are a journaling assistant. Walk the user through these questions in order using the ask_question tool, record each answer with record_answer, then call complete_session with a summary of the user's day.
43	
44	Questions:
45	${set.questions.map((q) => `${q.id}: ${q.text} (answer_type: ${q.answer_type}${q.min_answers ? `, at least ${q.min_answers} answers` : ""})`).join("\n")}`;
46	
47	export async function runSession(opts: {
48	  questionSet: QuestionSet;
49	  client: SessionClient;
50	  model: LanguageModel;
51	}): Promise<SessionResult> {
52	  const { questionSet, client, model } = opts;
53	  const answers: SessionResult["answers"] = {};
54	  let summary: string | undefined;
55	
56	  const tools = {
57	    ask_question: tool({
58	      description:
59	        "Ask the user one journaling question; the client renders the widget.",
60	      inputSchema: askQuestionInput,
61	      // no execute: client-side tool — the loop below supplies the result
62	    }),
63	    record_answer: tool({
64	      description: "Record the validated answer for one question.",
65	      inputSchema: recordAnswerInput,
66	      execute: async ({ question_id, ...rest }) => {
67	        const question = questionSet.questions.find(
68	          (q) => q.id === question_id,
69	        );
70	        const min = question?.min_answers ?? 1;
71	        if (Array.isArray(rest.value) && rest.value.length < min) {
72	          return {
73	            recorded: false,
74	            error: `This question needs at least ${min} answers.`,
75	          };
76	        }
77	        answers[question_id] = rest;
78	        return { recorded: true };
79	      },
80	    }),
81	    complete_session: tool({
82	      description: "Finish the session with a summary of the journal entry.",
83	      inputSchema: completeSessionInput,
84	      execute: async (input) => {
85	        summary = input.summary;
86	        return { completed: true };
87	      },
88	    }),
89	  };
90	
91	  const messages: ModelMessage[] = [
92	    { role: "user", content: "I am ready to start my journaling session." },
93	  ];
94	
95	  // ponytail: generous cap — a poweruser recording 20 gratitudes must never hit it;
96	  // tighten with real usage data once PostHog is wired (issue #5).
97	  const maxRounds = questionSet.questions.length * 6 + 20;
98	  let rounds = 0;
99	
100	  while (summary === undefined) {
101	    if (++rounds > maxRounds) {
102	      throw new Error(
