78	            error: `This question needs at least ${min} answers.`,
79	          };
80	        }
81	        answers[question_id] = answer;
82	        return { recorded: true };
83	      },
84	    }),
85	    complete_session: tool({
86	      description: "Finish the session with a summary of the journal entry.",
87	      inputSchema: completeSessionInput,
88	      execute: async (input) => {
