121	    if (result.finishReason !== "tool-calls") continue;
122	
123	    for (const call of result.toolCalls) {
124	      if (call.toolName !== "ask_question") continue;
125	      const value = await client.askQuestion(call.input as AskQuestionInput);
126	      messages.push({
