17	export async function judgeSession(opts: {
18	  model: LanguageModel;
19	  transcript: string;
20	  rubrics: string[];
21	  /** What the assistant was supposed to do — e.g. the question set. */
22	  context?: string;
23	}): Promise<Verdict[]> {
24	  const { model, transcript, rubrics, context } = opts;
25	  const { object } = await generateObject({
26	    model,
27	    schema: verdictSchema,
28	    // Deterministic grading: the judge must not be a second source of variance.
29	    temperature: 0,
30	    prompt: `You are grading a journaling-assistant conversation against rubrics.
31	For EACH rubric, decide pass/fail for the assistant's behavior in the transcript
32	and give a one-sentence reason. Return one verdict per rubric, in order.
33	${context ? `\nSession setup:\n${context}\n` : ""}
34	Rubrics:
35	${rubrics.map((r, i) => `${i + 1}. ${r}`).join("\n")}
36	
37	Transcript:
38	${transcript}`,
39	  });
40	  return object.verdicts;
41	}

1	export type ModelRates = {
2	  /** USD per million input tokens */
3	  inputPerM: number;
4	  /** USD per million cache-read input tokens; absent = billed at inputPerM */
5	  cacheReadPerM?: number;
6	  /** USD per million output tokens */
7	  outputPerM: number;
8	};
9	
10	export type TokenUsage = {
11	  /** Total input tokens — INCLUSIVE of cacheReadTokens (ai v7 semantics). */
12	  inputTokens: number;
13	  cacheReadTokens: number;
14	  outputTokens: number;
15	};
16	
17	// Rates for the default model only, verified against the gateway catalog on
18	// 2026-08-23; the benchmark reads live prices, this is for the PR-gate eval.
19	// gpt-oss-120b publishes no cache-read rate, so cached tokens bill at the
20	// input rate here (conservative — the live reading was 97% cached).
21	export const MODEL_RATES: Record<string, ModelRates> = {
22	  "openai/gpt-oss-120b": { inputPerM: 0.1, outputPerM: 0.5 },
23	};
24	
25	const TOKENS_PER_MILLION = 1_000_000;
26	
27	export function sessionCostUsd(
28	  usages: TokenUsage[],
29	  rates: ModelRates,
30	): number {
31	  const input = usages.reduce((sum, u) => sum + u.inputTokens, 0);
32	  const cached = usages.reduce((sum, u) => sum + u.cacheReadTokens, 0);
33	  const output = usages.reduce((sum, u) => sum + u.outputTokens, 0);
34	  const cacheRate = rates.cacheReadPerM ?? rates.inputPerM;
35	  return (
36	    ((input - cached) * rates.inputPerM +
37	      cached * cacheRate +
38	      output * rates.outputPerM) /
39	    TOKENS_PER_MILLION
40	  );
41	}

