25	// Union on answer_type so min_answers only exists where the value is a list.
26	export type Question = { id: string; text: string } & (
27	  | { answer_type: ScalarAnswerType; min_answers?: never }
28	  | { answer_type: ListAnswerType; min_answers?: number }
