60	function buildSessionTools(
61	  questionSet: QuestionSet,
62	  answers: SessionResult["answers"],
63	  asked: Set<string>,
64	  onComplete: (summary: string) => void,
65	) {
66	  return {
67	    ask_question: tool({
68	      description:
