70	      inputSchema: askQuestionInput,
71	      // no execute: client-side tool — the session loop supplies the result
72	    }),
73	    record_answer: tool({
74	      description: "Record the validated answer for one question.",
75	      inputSchema: recordAnswerInput,
76	      execute: async ({ question_id, answer }) => {
77	        const question = questionSet.questions.find(
