export async function advanceSession(opts: {
  questionSet: QuestionSet;
  model: LanguageModel;
  messages: ModelMessage[];
  answer?: SessionAnswer;
  temperature?: number;
  attribution?: { distinctId: string; sessionId: string };
  promptId?: string;
