        pending: {
          toolCallId: ask.toolCallId,
          input: ask.input as AskQuestionInput,
        },
      };
    }
  }

  return {
    status: "completed",
    messages,
    usage,
    roundLatenciesMs,
    promptId: prompt.id,
    entry: { summary, answers },
  };
