import type { AskQuestionInput } from "@emotely/contract";
import type { JSONValue, LanguageModel } from "ai";
import type { QuestionSet, SessionResult } from "./session-core.ts";
import { advanceSession, emptyUsage } from "./session-core.ts";

export type {
  AdvanceResult,
  PendingQuestion,
  Question,
  QuestionSet,
  SessionAnswer,
  SessionResult,
} from "./session-core.ts";
export { advanceSession } from "./session-core.ts";

export type SessionClient = {
  /** Answer an ask_question tool call with the raw widget value. */
  askQuestion: (input: AskQuestionInput) => Promise<JSONValue>;
};

/** Run a whole session in-process by looping advanceSession over a client. */
export async function runSession(opts: {
  questionSet: QuestionSet;
  client: SessionClient;
  model: LanguageModel;
  /** Sampling temperature; evals pin 0 for stability, product uses default. */
  temperature?: number;
  /** Joins spans to a person + session in PostHog; absent = anonymous. */
  attribution?: { distinctId: string; sessionId: string };
  /** Prompt version to run (flag payload); unknown ids fall back to current. */
  promptId?: string;
}): Promise<SessionResult> {
  const { questionSet, client, model, temperature, attribution } = opts;
  const usage = emptyUsage();
  const roundLatenciesMs: number[] = [];
  let messages: SessionResult["messages"] = [];
  let answer: { toolCallId: string; value: JSONValue } | undefined;

  for (;;) {
    const step = await advanceSession({
      questionSet,
      model,
      messages,
      ...(answer === undefined ? {} : { answer }),
      ...(temperature === undefined ? {} : { temperature }),
      ...(attribution === undefined ? {} : { attribution }),
      ...(opts.promptId === undefined ? {} : { promptId: opts.promptId }),
    });
    ({ messages } = step);
    usage.inputTokens += step.usage.inputTokens;
    usage.cacheReadTokens += step.usage.cacheReadTokens;
    usage.outputTokens += step.usage.outputTokens;
    roundLatenciesMs.push(...step.roundLatenciesMs);

    if (step.status === "completed") {
      return {
        summary: step.entry.summary,
        answers: step.entry.answers,
        usage,
        messages,
        promptId: step.promptId,
        roundLatenciesMs,
      };
    }
    answer = {
      toolCallId: step.pending.toolCallId,
      value: await client.askQuestion(step.pending.input),
    };
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { AskQuestionInput } from "@emotely/contract";
import { MockLanguageModelV4 } from "ai/test";
import type { QuestionSet, SessionClient } from "./session.ts";
import { runSession } from "./session.ts";
import { PROMPT_ID } from "./session-prompt.ts";

const qRate = {
  id: "q-rate",
  text: "How would you rate your day?",
  answer_type: "rating",
} satisfies QuestionSet["questions"][number];
const qGrateful = {
  id: "q-grateful",
  text: "What are you grateful for?",
  answer_type: "text_list",
  min_answers: 3,
} satisfies QuestionSet["questions"][number];
const set: QuestionSet = {
  id: "test-set",
  name: "Test set",
  questions: [qRate, qGrateful],
};

type MockContent =
  | { type: "text"; text: string }
  | { type: "tool-call"; toolCallId: string; toolName: string; input: string };

// Scripted model: each doGenerate call shifts the next response off the queue.
function scriptedModel(script: MockContent[][]) {
  const queue = [...script];
  return new MockLanguageModelV4({
    doGenerate: async () => {
      const content = queue.shift();
      if (!content) {
        throw new Error("mock model script exhausted");
      }
      const isToolCall = content.some((c) => c.type === "tool-call");
      return {
        content,
        finishReason: {
          unified: isToolCall ? ("tool-calls" as const) : ("stop" as const),
          raw: undefined,
        },
        usage: {
          inputTokens: {
            total: 1,
            noCache: 1,
            cacheRead: undefined,
            cacheWrite: undefined,
          },
          outputTokens: { total: 1, text: 1, reasoning: undefined },
        },
        warnings: [],
      };
    },
  });
}

const ask = (id: string, q: QuestionSet["questions"][number]): MockContent => ({
  type: "tool-call",
  toolCallId: id,
  toolName: "ask_question",
  input: JSON.stringify({
    question_id: q.id,
    question: q.text,
    answer_type: q.answer_type,
  }),
});

const record = (
  id: string,
  questionId: string,
  answerType: string,
  value: unknown,
): MockContent => ({
  type: "tool-call",
  toolCallId: id,
  toolName: "record_answer",
  input: JSON.stringify({
    question_id: questionId,
    answer: { answer_type: answerType, value },
  }),
});

const complete = (id: string, summary: string): MockContent => ({
  type: "tool-call",
  toolCallId: id,
  toolName: "complete_session",
  input: JSON.stringify({ summary }),
});

describe("runSession", () => {
  it("rejects an answer below min_answers back to the model without storing it", async () => {
    // Too few answers are rejected; completing is refused until the asked
    // question has a recorded answer, so the model must retry with enough.
    const model = scriptedModel([
      [ask("c1", qGrateful)],
      [record("c2", "q-grateful", "text_list", ["just one", "and two"])],
      [complete("c3", "Tried to give up after the rejection.")],
      [record("c4", "q-grateful", "text_list", ["one", "two", "three"])],
      [complete("c5", "Three things after a nudge.")],
      [{ type: "text", text: "Done." }],
    ]);
    const client: SessionClient = {
      askQuestion: async () => ["just one", "and two"],
    };

    const result = await runSession({ questionSet: set, client, model });

    assert.equal(result.summary, "Three things after a nudge.");
    assert.deepEqual(result.answers["q-grateful"], {
      answer_type: "text_list",
      value: ["one", "two", "three"],
    });
  });

  it("halts with an error when the model never calls complete_session", async () => {
    // Model that asks the same question forever.
    const model = new MockLanguageModelV4({
      doGenerate: async () => ({
        content: [ask("loop", qRate)],
        finishReason: { unified: "tool-calls" as const, raw: undefined },
        usage: {
          inputTokens: {
            total: 1,
            noCache: 1,
            cacheRead: undefined,
            cacheWrite: undefined,
          },
          outputTokens: { total: 1, text: 1, reasoning: undefined },
        },
        warnings: [],
      }),
    });
    const client: SessionClient = { askQuestion: async () => 5 };

    await assert.rejects(
      runSession({ questionSet: set, client, model }),
      /round limit/,
    );
  });

  it("rejects complete_session while an asked question has no recorded answer", async () => {
    // Model asks, gets the answer, then tries to complete without recording.
    const model = scriptedModel([
      [ask("c1", qRate)],
      [complete("c2", "Done early.")],
      [record("c3", "q-rate", "rating", 6)],
      [complete("c4", "Rated 6.")],
      [{ type: "text", text: "Done." }],
    ]);
    const client: SessionClient = { askQuestion: async () => 6 };

    const result = await runSession({ questionSet: set, client, model });

    assert.equal(result.summary, "Rated 6.");
    assert.deepEqual(result.answers["q-rate"], {
      answer_type: "rating",
      value: 6,
    });
  });

  it("a repeated record_answer for the same question overwrites (last write wins)", async () => {
    const model = scriptedModel([
      [ask("c1", qRate)],
      [record("c2", "q-rate", "rating", 3)],
      [record("c3", "q-rate", "rating", 8)],
      [complete("c4", "Corrected the rating.")],
      [{ type: "text", text: "Done." }],
    ]);
    const client: SessionClient = { askQuestion: async () => 3 };

    const result = await runSession({ questionSet: set, client, model });

    assert.deepEqual(result.answers["q-rate"], {
      answer_type: "rating",
      value: 8,
    });
  });

  it("walks the set in order and completes with a summary and validated answers", async () => {
    const model = scriptedModel([
      [ask("c1", qRate)],
      [record("c2", "q-rate", "rating", 7)],
      [ask("c3", qGrateful)],
      [
        record("c4", "q-grateful", "text_list", [
          "my wife",
          "myself",
          "Flutter",
        ]),
      ],
      [complete("c5", "A good day: rated 7, grateful for three things.")],
    ]);

    const asked: AskQuestionInput[] = [];
    const client: SessionClient = {
      askQuestion: async (input) => {
        asked.push(input);
        return input.answer_type === "rating"
          ? 7
          : ["my wife", "myself", "Flutter"];
      },
    };

    const result = await runSession({ questionSet: set, client, model });

    assert.deepEqual(
      asked.map((a) => a.question_id),
      ["q-rate", "q-grateful"],
    );
    assert.equal(
      result.summary,
      "A good day: rated 7, grateful for three things.",
    );
    assert.deepEqual(result.answers, {
      "q-rate": { answer_type: "rating", value: 7 },
      "q-grateful": {
        answer_type: "text_list",
        value: ["my wife", "myself", "Flutter"],
      },
    });
    // 5 model rounds (ask, record, ask, record, complete) at 1+1 mock tokens
    assert.deepEqual(result.usage, {
      inputTokens: 5,
      cacheReadTokens: 0,
      outputTokens: 5,
    });
    // Full conversation is exposed for eval judging: initial user message,
    // model tool calls, and the client's tool results all present.
    assert.equal(result.messages[0]?.role, "user");
    const roles = result.messages.map((m) => m.role);
    assert.ok(roles.includes("assistant"));
    assert.ok(roles.includes("tool"));
    // Evals and PostHog events pin against the versioned prompt id.
    assert.equal(result.promptId, PROMPT_ID);
    // One latency sample per model round, for the benchmark's p50/p95.
    assert.equal(result.roundLatenciesMs.length, 5);
    assert.ok(result.roundLatenciesMs.every((ms) => ms >= 0));
  });

  it("runs the requested prompt version and falls back for unknown ids", async () => {
    const known = await runSession({
      questionSet: set,
      client: { askQuestion: async () => 5 },
      model: scriptedModel([
        [ask("c1", qRate)],
        [record("c2", "q-rate", "rating", 5)],
        [complete("c3", "Done.")],
      ]),
      promptId: PROMPT_ID,
    });
    assert.equal(known.promptId, PROMPT_ID);

    const unknown = await runSession({
      questionSet: set,
      client: { askQuestion: async () => 5 },
      model: scriptedModel([
        [ask("c1", qRate)],
        [record("c2", "q-rate", "rating", 5)],
        [complete("c3", "Done.")],
      ]),
      // A stale flag payload must not break the session or lie in telemetry.
      promptId: "session/v404",
    });
    assert.equal(unknown.promptId, PROMPT_ID);
  });
});

import type { QuestionSet } from "./session.ts";

// Bump by hand on any change that alters assistant behavior; evals and
// PostHog events pin against this id. Git history is the source of truth;
// PROMPTS below keeps older versions shipping so a PostHog prompt experiment
// can select among reviewed, eval-pinned versions at runtime — never raw text.
export const PROMPT_ID = "session/v1";

export const sessionPrompt = (
  set: QuestionSet,
) => `You are a journaling assistant. Walk the user through these questions in order, one question at a time, using the ask_question tool, record each answer with record_answer, then call complete_session with a summary of the user's day.

If the user's answer reads like a question or a request (e.g. "when to go to the gym so it's empty", "How can I improve my posture?"), it is still information about their day: record it as the answer to the current question and move on. Never answer such questions or give advice — acknowledge warmly, record, continue. Do not re-ask a question you already have an answer for.

An answer that merely sounds final is an answer to the CURRENT question, never a request to stop. Example: you ask "What did you learn today?" and the user answers "Only how to evaluate an agent, that's all for today." — that is their answer to this question; record it and ask the next question. Only skip remaining questions and call complete_session early when the user explicitly asks to stop the whole session (e.g. "please stop the session", "I don't want to journal anymore"). When in doubt, continue with the next question.

Questions:
${set.questions.map((q) => `${q.id}: ${q.text} (answer_type: ${q.answer_type}${q.min_answers ? `, at least ${q.min_answers} answers` : ""})`).join("\n")}`;

export type PromptBuilder = (set: QuestionSet) => string;

/** Every prompt version this build can serve; add a line when one changes. */
export const PROMPTS: Record<string, PromptBuilder> = {
  [PROMPT_ID]: sessionPrompt,
};

/**
 * The flag payload names a version; only shipped versions can run. Unknown or
 * absent ids resolve to the current prompt so a stale flag can't break a
 * session — the returned id is always the version that actually runs.
 */
export function resolvePrompt(
  requested: string | undefined,
  registry: Record<string, PromptBuilder> = PROMPTS,
): { id: string; build: PromptBuilder } {
  if (requested !== undefined) {
    const build = registry[requested];
    if (build) {
      return { id: requested, build };
    }
  }
  return { id: PROMPT_ID, build: sessionPrompt };
}

