import 'package:emotely/common/exceptions/emotely_exception.dart';
import 'package:emotely/common/extensions/color_extension.dart';
import 'package:emotely/common/extensions/extensions.dart';
import 'package:flutter/material.dart';

/// A [TextEditingController] that allows the user to input text with
/// hex-encoded colors being displayed as colored boxes.
///
/// It handles the insertion of color strings and displays colored boxes in
/// their place in the text field. The usual text editing
/// behavior is preserved.
///
/// The color strings are expected to be in the format `#RRGGBB`.
class ColorTextEditingController extends TextEditingController {
  ColorTextEditingController({super.text});

  // Matches hex-encoded color strings in the format `#RRGGBB`.
  static final RegExp hexColorRegex = RegExp(r'#[0-9a-fA-F]{6}\b');

  @override
  TextSpan buildTextSpan({
    required final BuildContext context,
    final TextStyle? style,
    final bool? withComposing,
  }) {
    final List<InlineSpan> children = _parseText(context, style);

    return TextSpan(style: style, children: children);
  }

  List<InlineSpan> _parseText(
    final BuildContext context,
    final TextStyle? style,
  ) {
    final List<InlineSpan> spans = <InlineSpan>[];
    int start = 0;

    for (final RegExpMatch hexColorMatch in hexColorRegex.allMatches(text)) {
      if (hexColorMatch.start > start) {
        spans.add(
          TextSpan(
            text: text.substring(start, hexColorMatch.start),
            style: style,
          ),
        );
      }

      final String hexColorString = hexColorMatch.group(0)!;

      ColorStringUtils.fromString(hexColorString).match(
        // This is not testable, because the regexp
        // only allows valid color strings
        (final EmotelyError error) => spans.add(
          TextSpan(
            text: hexColorString,
            style: style?.copyWith(color: Colors.red),
          ),
        ),
        (final Color color) {
          final int length = hexColorString.length;
          final int lastCharIndex = length - 1;
          for (int i = 0; i < length; i++) {
            spans.add(
              WidgetSpan(
                child: Semantics(
                  label:
                      '${context.intl.semanticsColorSymbol} '
                      '$hexColorString $i',
                  container: true,
                  child: Container(
                    width: 2.3,
                    height: 16,
                    decoration: BoxDecoration(
                      color: color,
                      // first and last color widget should have rounded corners
                      borderRadius: i == 0
                          ? const BorderRadius.only(
                              topLeft: Radius.circular(4),
                              bottomLeft: Radius.circular(4),
                            )
                          : i == lastCharIndex
                          ? const BorderRadius.only(
                              topRight: Radius.circular(4),
                              bottomRight: Radius.circular(4),
                            )
                          : null,
                    ),
                  ),
                ),
              ),
            );
          }
        },
      );

      start = hexColorMatch.end;
    }

    if (start < text.length) {
      spans.add(TextSpan(text: text.substring(start), style: style));
    }

    return spans;
  }

  /// Inserts the given [textToInsert] at the current selection.
  void insertTextAtSelection(final String textToInsert) {
    final TextSelection selection = adjustSelection(
      previousSelection: value.selection,
      newSelection: value.selection,
      newText: value.text,
    );

    final String newText = text.replaceRange(
      selection.baseOffset,
      selection.extentOffset,
      textToInsert,
    );

    value = value.copyWith(
      text: newText,
      selection: TextSelection.collapsed(
        offset: selection.baseOffset + textToInsert.length,
      ),
    );
  }

  @override
  set value(final TextEditingValue newValue) {
    // Ensure the cursor moves over the color widgets properly
    final TextSelection adjustedSelection = adjustSelection(
      previousSelection: value.selection,
      newSelection: newValue.selection,
      newText: newValue.text,
    );
    super.value = newValue.copyWith(selection: adjustedSelection);
  }

  /// Adjusts the selection to account for the color widgets.
  ///
  /// This method ensures that the selection does not land inside a color
  /// widget. If the selection is inside a color widget, it will be moved to
  /// the start or end of the color widget, depending on the direction of the
  /// selection.
  @visibleForTesting
  TextSelection adjustSelection({
    required final TextSelection previousSelection,
    required final TextSelection newSelection,
    required final String newText,
  }) {
    final RegExp hexColorRegex = RegExp(r'#[0-9a-fA-F]{6}\b');
    int leading = newSelection.baseOffset < newSelection.extentOffset
        ? newSelection.baseOffset
        : newSelection.extentOffset;
    int trailing = newSelection.extentOffset > newSelection.baseOffset
        ? newSelection.extentOffset
        : newSelection.baseOffset;

    // This handles the case where the user is deleting a character
    if (previousSelection.isCollapsed && (leading - trailing) == -1) {
      return newSelection;
    }
    final bool isSelecting = leading != trailing;

    for (final RegExpMatch hexColorMatch in hexColorRegex.allMatches(newText)) {
      // Handle base offset
      final bool isBaseOffsetInsideColor =
          leading > hexColorMatch.start && leading < hexColorMatch.end;
      if (isBaseOffsetInsideColor) {
        if (isSelecting || leading == hexColorMatch.end - 1) {
          leading = hexColorMatch.start;
        } else {
          leading = hexColorMatch.end;
        }
      }
      // Handle extent offset
      final bool isExtentOffsetInsideColor =
          trailing > hexColorMatch.start && trailing < hexColorMatch.end;
      if (isExtentOffsetInsideColor) {
        if (!isSelecting && trailing == hexColorMatch.end - 1) {
          trailing = hexColorMatch.start;
        } else {
          trailing = hexColorMatch.end;
        }
      }
    }

    return newSelection.copyWith(
      baseOffset: leading.clamp(0, newText.length),
      extentOffset: trailing.clamp(0, newText.length),
    );
  }
}
import 'package:emotely/common/exceptions/emotely_exception.dart';
import 'package:emotely/common/extensions/color_extension.dart';
import 'package:flutter/material.dart';

/// A class that displays text with hex-encoded color strings
/// replaced with colored boxes.
///
/// Color codes are expected be in the format `#RRGGBB`.
class ColorText extends StatelessWidget {
  const ColorText(this.text, {this.style, super.key});

  final String text;
  final TextStyle? style;

  /// Parses the text and returns a list of [InlineSpan]s with the color
  /// strings replaced with colored boxes.
  List<InlineSpan> parseText(final String text) {
    // Matches hex-encoded color strings in the format `#RRGGBB`.
    final RegExp hexColorRegex = RegExp(r'#[0-9a-fA-F]{6}\b');
    final List<InlineSpan> spans = <InlineSpan>[];
    int start = 0;

    for (final RegExpMatch hexColorMatch in hexColorRegex.allMatches(text)) {
      if (hexColorMatch.start > start) {
        spans.add(
          TextSpan(
            text: text.substring(start, hexColorMatch.start),
            style: style,
          ),
        );
      }

      final String hexColorString = hexColorMatch.group(0)!;
      ColorStringUtils.fromString(hexColorString).match(
        // This is not testable, because the regexp
        // only allows valid color strings
        (final EmotelyError error) => spans.add(
          TextSpan(
            text: hexColorString,
            style: const TextStyle(color: Colors.red),
          ),
        ),
        (final Color color) => spans.add(
          WidgetSpan(
            child: ColorBox(color: color, semanticLabel: hexColorString),
          ),
        ),
      );

      start = hexColorMatch.end;
    }

    if (start < text.length) {
      spans.add(TextSpan(text: text.substring(start), style: style));
    }

    return spans;
  }

  @override
  Widget build(final BuildContext context) {
    return Text.rich(
      semanticsLabel: text,
      TextSpan(children: parseText(text)),
      style: style,
    );
  }
}

class ColorBox extends StatelessWidget {
  const ColorBox({required this.color, required this.semanticLabel, super.key});

  final String semanticLabel;
  final Color color;

  @override
  Widget build(final BuildContext context) {
    return Semantics(
      label: semanticLabel,
      container: true,
      child: Container(
        width: 16,
        height: 16,
        margin: const EdgeInsets.symmetric(horizontal: 2),
        decoration: BoxDecoration(
          color: color,
          borderRadius: BorderRadius.circular(4),
        ),
      ),
    );
  }
}

