import 'package:emotely/common/extensions/extensions.dart';
import 'package:emotely/ui/pages/journaling_assistant/widgets/color_text_editing_controller.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:patrol_finders/patrol_finders.dart';

import '../../../../common/utils.dart';

void main() {
  group('ColorTextEditingController', () {
    group('value= adjusts selection correctly for', () {
      test('Empty String', () {
        const String newText = '';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 0,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 0);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 0));
      });

      test('No Colors', () {
        const String newText = 'Hello World';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 5,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 5);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 5));
      });

      test('Single Color at Start, Cursor Before Color', () {
        const String newText = '#FF5733 some text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 0,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 0);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.selection, const TextSelection.collapsed(offset: 0));
      });

      test('Single Color at End, Cursor Before Color', () {
        const String newText = 'some text #FF5733';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 10,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 10);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 10));
      });

      test('Single Color in Middle, Cursor Before Color', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 5,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 5);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 5));
      });

      test('Cursor Before Single Color', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 4,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 4);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 4));
      });

      test('Cursor Inside Hex Code in Single Color', () {
        const String newText = 'some #FF5733 text';
        const TextSelection selection = TextSelection.collapsed(offset: 6);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 12));
      });

      test('Cursor Moves inside Hex Code from before, Move to End', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 2,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 6);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 12));
      });

      test('Cursor Moves inside Hex Code from after, Move to End', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 14,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 6);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 12));
      });

      test('Cursor Moves behind single Hex Code', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 12,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 13);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 13));
      });

      test('Cursor Moves to Before Hex Code, Move to Before', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 12,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 5);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 5));
      });

      test('Cursor Moves inside Hex Code from right, Move to Before', () {
        const String newText = 'some #FF5733 text';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 12,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 11);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 5));
      });

      test('Multiple Colors, Cursor Before First Color', () {
        const String newText = '#FF5733 some #33FF57 text #5733FF';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 0,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 0);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 0));
      });

      test('Multiple Colors, Cursor After Last Color', () {
        const String newText = '#FF5733 some #33FF57 text #5733FF';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 33,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 33);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 33));
      });

      test('Multiple Colors, Cursor Between Colors', () {
        const String newText = '#FF5733 some #33FF57 text #5733FF';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 12,
        );
        const TextSelection selection = TextSelection.collapsed(offset: 13);
        final ColorTextEditingController controller =
            ColorTextEditingController();

        controller.value = controller.value.copyWith(
          text: newText,
          selection: previousSelection,
        );
        expect(controller.text, newText);
        expect(controller.selection, previousSelection);

        controller.value = controller.value.copyWith(
          text: newText,
          selection: selection,
        );
        expect(controller.text, newText);
        expect(controller.selection, const TextSelection.collapsed(offset: 13));
      });

      test(
        'Multiple Colors, Cursor Moves to Inside First Hex Code, Move to End',
        () {
          const String newText = '#FF5733 #33FF57 #5733FF';
          const TextSelection previousSelection = TextSelection.collapsed(
            offset: 8,
          );
          const TextSelection selection = TextSelection.collapsed(offset: 4);
          final ColorTextEditingController controller =
              ColorTextEditingController();

          controller.value = controller.value.copyWith(
            text: newText,
            selection: previousSelection,
          );
          expect(controller.text, newText);
          expect(controller.selection, previousSelection);

          controller.value = controller.value.copyWith(
            text: newText,
            selection: selection,
          );
          expect(controller.text, newText);
          expect(
            controller.selection,
            const TextSelection.collapsed(offset: 7),
          );
        },
      );

      test('Cursor Moves inside First Hex Code from left, Move to End', () {
        const String newText = '#FF5733 #33FF57 #5733FF';
        const TextSelection previousSelection = TextSelection.collapsed(
          offset: 0,
        );
