            createTestWidget(
              TextField(controller: ColorTextEditingController()),
            ),
          );

          await $(TextField).enterText('$colorString some text');

          final BuildContext context = $.tester.element($(TextField));

          final Finder firstSemantics = find.bySemanticsLabel(
            '${context.intl.semanticsColorSymbol} $colorString 0',
          );
          final Finder lastSemantics = find.bySemanticsLabel(
            '${context.intl.semanticsColorSymbol} $colorString 6',
          );

