import 'package:emotely/session/widgets/color_input.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

import '../../helpers/helpers.dart';

void main() {
  group(ColorInput, () {
    Future<Submitted> pumpTestWidget(WidgetTester tester) async {
      final submitted = Submitted();
      await tester.pumpApp(ColorInput(onSubmit: submitted.call));
      return submitted;
    }

    String fieldText(WidgetTester tester) => tester
        .widget<TextField>(find.byKey(ColorInput.fieldKey))
        .controller!
        .text;

    Future<void> type(WidgetTester tester, String text) async {
      await tester.enterText(find.byKey(ColorInput.fieldKey), text);
      await tester.pump();
    }

    testWidgets('offers the whole palette, each announced by name', (
      tester,
    ) async {
      await pumpTestWidget(tester);

      expect(find.byType(IconButton), findsNWidgets(colorPalette.length));
      expect(find.byTooltip('teal'), findsOneWidget);
    });

    testWidgets('submit is disabled until the text holds a color', (
      tester,
    ) async {
      await pumpTestWidget(tester);

      expect(isSubmitEnabled(tester, ColorInput.submitKey), isFalse);

      await type(tester, 'no color yet');

      expect(isSubmitEnabled(tester, ColorInput.submitKey), isFalse);

      await type(tester, 'a #ff8800 day');

      expect(isSubmitEnabled(tester, ColorInput.submitKey), isTrue);
    });

    testWidgets('a palette tap inserts its code at the caret', (tester) async {
      await pumpTestWidget(tester);
      await type(tester, 'today felt ');

      await tester.tap(find.byKey(ColorInput.paletteKey('red')));
      await tester.pump();

      expect(fieldText(tester), 'today felt #E53935 ');
      expect(isSubmitEnabled(tester, ColorInput.submitKey), isTrue);
    });

    testWidgets('submits every color in order of appearance', (tester) async {
      final submitted = await pumpTestWidget(tester);
      await type(tester, 'mostly #00ff00, then #ABCDEF and #12345');

      await tester.tap(find.byKey(ColorInput.submitKey));
      await tester.pump();

      expect(
        submitted.single,
        const Answer.color([Color(0xFF00FF00), Color(0xFFABCDEF)]),
      );
    });

    testWidgets('meets accessibility guidelines', (tester) async {
      await tester.expectMeetsAccessibilityGuidelines(
        appWrapper(const ColorInput(onSubmit: ignoreAnswer)),
        prepare: (tester) => type(tester, 'a #FF8800 day'),
      );
    });
  });
}

import 'package:emotely/contract/contract.dart';
import 'package:emotely/session/widgets/emoji_input.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

import '../../helpers/helpers.dart';

void main() {
  group(EmojiInput, () {
    Future<Submitted> pumpTestWidget(WidgetTester tester) async {
      final submitted = Submitted();
      await tester.pumpApp(EmojiInput(onSubmit: submitted.call));
      return submitted;
    }

    Future<void> toggle(WidgetTester tester, String emoji) async {
      await tester.tap(find.byKey(EmojiInput.chipKey(emoji)));
      await tester.pump();
    }

    testWidgets('offers the whole palette, each announced by name', (
      tester,
    ) async {
      await pumpTestWidget(tester);

      expect(find.byType(FilterChip), findsNWidgets(emojiPalette.length));
      expect(find.bySemanticsLabel('grateful'), findsOneWidget);
    });

    testWidgets('submit is disabled until an emoji is picked', (tester) async {
      await pumpTestWidget(tester);

      expect(isSubmitEnabled(tester, EmojiInput.submitKey), isFalse);

      await toggle(tester, '😊');

      expect(isSubmitEnabled(tester, EmojiInput.submitKey), isTrue);
    });

    testWidgets('picking again deselects', (tester) async {
      await pumpTestWidget(tester);
      await toggle(tester, '😊');

      await toggle(tester, '😊');

      expect(isSubmitEnabled(tester, EmojiInput.submitKey), isFalse);
    });

    testWidgets('submits the picked emoji in palette order', (tester) async {
      final submitted = await pumpTestWidget(tester);
      await toggle(tester, '😢');
      await toggle(tester, '😊');

      await tester.tap(find.byKey(EmojiInput.submitKey));
      await tester.pump();

      expect(submitted.single, const Answer.emoji(['😊', '😢']));
    });

    testWidgets('meets accessibility guidelines', (tester) async {
      await tester.expectMeetsAccessibilityGuidelines(
        appWrapper(const EmojiInput(onSubmit: ignoreAnswer)),
        prepare: (tester) => toggle(tester, '🙏'),
      );
    });
  });
}

import 'package:emotely/contract/contract.dart';
import 'package:emotely/session/widgets/rating_input.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

import '../../helpers/helpers.dart';

void main() {
  group(RatingInput, () {
    Future<Submitted> pumpTestWidget(WidgetTester tester) async {
      final submitted = Submitted();
      await tester.pumpApp(RatingInput(onSubmit: submitted.call));
      return submitted;
    }

    Future<void> pick(WidgetTester tester, int value) async {
      await tester.tap(find.byKey(RatingInput.chipKey(value)));
      await tester.pump();
    }

    testWidgets('offers exactly the values 1 to 10', (tester) async {
      await pumpTestWidget(tester);

      expect(find.byType(ChoiceChip), findsNWidgets(10));
      expect(find.byKey(RatingInput.chipKey(1)), findsOneWidget);
      expect(find.byKey(RatingInput.chipKey(10)), findsOneWidget);
    });

    testWidgets('submit is disabled until a value is picked', (tester) async {
      await pumpTestWidget(tester);

      expect(isSubmitEnabled(tester, RatingInput.submitKey), isFalse);

      await pick(tester, 7);

      expect(isSubmitEnabled(tester, RatingInput.submitKey), isTrue);
    });

    testWidgets('submits the last picked value', (tester) async {
      final submitted = await pumpTestWidget(tester);
      await pick(tester, 7);
      await pick(tester, 3);

      await tester.tap(find.byKey(RatingInput.submitKey));
      await tester.pump();

      expect(submitted.single, const Answer.rating(3));
      expect(
        tester.widget<ChoiceChip>(find.byKey(RatingInput.chipKey(3))).selected,
        isTrue,
      );
      expect(
        tester.widget<ChoiceChip>(find.byKey(RatingInput.chipKey(7))).selected,
        isFalse,
      );
    });

    testWidgets('meets accessibility guidelines', (tester) async {
      await tester.expectMeetsAccessibilityGuidelines(
        appWrapper(const RatingInput(onSubmit: ignoreAnswer)),
        prepare: (tester) => pick(tester, 8),
      );
    });
  });
}

import 'package:emotely/contract/contract.dart';
import 'package:emotely/session/widgets/longtext_input.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../helpers/helpers.dart';

void main() {
  group(LongtextInput, () {
    Future<Submitted> pumpTestWidget(WidgetTester tester) async {
      final submitted = Submitted();
      await tester.pumpApp(LongtextInput(onSubmit: submitted.call));
      return submitted;
    }

    Future<void> type(WidgetTester tester, String text) async {
      await tester.enterText(find.byKey(LongtextInput.fieldKey), text);
      await tester.pump();
    }

    testWidgets('submit is disabled until there is text', (tester) async {
      await pumpTestWidget(tester);

      expect(isSubmitEnabled(tester, LongtextInput.submitKey), isFalse);

      await type(tester, 'A quiet day.');

      expect(isSubmitEnabled(tester, LongtextInput.submitKey), isTrue);
    });

    testWidgets('whitespace alone does not count as text', (tester) async {
      await pumpTestWidget(tester);

      await type(tester, '   \n');

      expect(isSubmitEnabled(tester, LongtextInput.submitKey), isFalse);
    });

    testWidgets('submits the trimmed text', (tester) async {
      final submitted = await pumpTestWidget(tester);
      await type(tester, '  A quiet, focused day.\n');

      await tester.tap(find.byKey(LongtextInput.submitKey));
      await tester.pump();

      expect(submitted.single, const Answer.longtext('A quiet, focused day.'));
    });

    testWidgets('meets accessibility guidelines', (tester) async {
      await tester.expectMeetsAccessibilityGuidelines(
        appWrapper(const LongtextInput(onSubmit: ignoreAnswer)),
      );
    });
  });
}

import 'package:emotely/contract/contract.dart';
import 'package:emotely/session/widgets/text_list_input.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

import '../../helpers/helpers.dart';

void main() {
  group(TextListInput, () {
    Future<Submitted> pumpTestWidget(WidgetTester tester) async {
      final submitted = Submitted();
      await tester.pumpApp(TextListInput(onSubmit: submitted.call));
      return submitted;
    }

    Future<void> type(WidgetTester tester, String text) async {
      await tester.enterText(find.byKey(TextListInput.fieldKey), text);
      await tester.pump();
    }

    Future<void> tapAdd(WidgetTester tester) async {
      await tester.tap(find.byKey(TextListInput.addKey));
      await tester.pump();
    }

    testWidgets('submit is disabled until something is typed', (tester) async {
      await pumpTestWidget(tester);

      expect(isSubmitEnabled(tester, TextListInput.submitKey), isFalse);

      await type(tester, 'my wife');

      expect(isSubmitEnabled(tester, TextListInput.submitKey), isTrue);
    });

    testWidgets('add turns the typed text into a chip and clears the field', (
      tester,
    ) async {
      await pumpTestWidget(tester);
      await type(tester, ' my wife ');

      await tapAdd(tester);

      expect(find.byKey(TextListInput.itemKey(0)), findsOneWidget);
      expect(find.text('my wife'), findsOneWidget);
      expect(
        tester
            .widget<TextField>(find.byKey(TextListInput.fieldKey))
            .controller
            ?.text,
        isEmpty,
      );
    });

    testWidgets('the keyboard action adds the item too', (tester) async {
      await pumpTestWidget(tester);
      await type(tester, 'Flutter');

      await tester.testTextInput.receiveAction(TextInputAction.done);
      await tester.pump();

      expect(find.byKey(TextListInput.itemKey(0)), findsOneWidget);
    });

    testWidgets('the keyboard action on an empty field adds nothing', (
      tester,
    ) async {
      await pumpTestWidget(tester);
      await type(tester, '  ');

      await tester.testTextInput.receiveAction(TextInputAction.done);
      await tester.pump();

      expect(find.byType(InputChip), findsNothing);
    });

    testWidgets('deleting a chip removes the item', (tester) async {
      await pumpTestWidget(tester);
      await type(tester, 'my wife');
      await tapAdd(tester);
      await type(tester, 'Flutter');
      await tapAdd(tester);

      await tester.tap(
        find.descendant(
          of: find.byKey(TextListInput.itemKey(0)),
          matching: find.byTooltip('Delete'),
        ),
      );
      await tester.pump();

      expect(find.byType(InputChip), findsOneWidget);
      expect(find.text('Flutter'), findsOneWidget);
      expect(find.text('my wife'), findsNothing);
    });

    testWidgets('submits the added items plus the pending text', (
      tester,
    ) async {
      final submitted = await pumpTestWidget(tester);
      await type(tester, 'my wife');
      await tapAdd(tester);
      await type(tester, 'myself');
      await tapAdd(tester);
      await type(tester, 'Flutter');

      await tester.tap(find.byKey(TextListInput.submitKey));
      await tester.pump();

      expect(
        submitted.single,
        const Answer.textList(['my wife', 'myself', 'Flutter']),
      );
    });

    testWidgets('meets accessibility guidelines with items present', (
      tester,
    ) async {
      await tester.expectMeetsAccessibilityGuidelines(
        appWrapper(const TextListInput(onSubmit: ignoreAnswer)),
        prepare: (tester) async {
          await type(tester, 'my wife');
          await tapAdd(tester);
          await type(tester, 'Flutter');
        },
      );
    });
  });
}
